-- Clown Shop NPC Script\n\nlocal Players = game:GetService("Players")\nlocal ReplicatedStorage = game:GetService("ReplicatedStorage")\n\n-- Create a remote event for communication\nlocal speedBoostEvent = Instance.new("RemoteEvent")\nspeedBoostEvent.Name = "SpeedBoostEvent"\nspeedBoostEvent.Parent = ReplicatedStorage\n\n-- Function to handle speed boost purchase\nlocal function onSpeedBoostPurchase(player, amount)\n    -- Check if the player has enough money\n    local leaderstats = player:FindFirstChild("leaderstats")\n    if leaderstats then\n        local money = leaderstats:FindFirstChild("Money")\n        if money and money.Value >= amount then\n            -- Deduct the money\n            money.Value = money.Value - amount\n            \n            -- Apply the speed boost\n            local speedBoost = Instance.new("BoolValue")\n            speedBoost.Name = "SpeedBoost"\n            speedBoost.Value = true\n            speedBoost.Parent = player\n            \n            -- Set a timer to remove the speed boost after a certain time\n            delay(30, function()\n                speedBoost:Destroy()\n            end)\n            \n            return true\n        end\n    end\n    \n    return false\nend\n\n-- Connect the remote event to the purchase function\nspeedBoostEvent.OnServerEvent:Connect(onSpeedBoostPurchase)